const later = (ms, value) =>
  new Promise((resolve) => setTimeout(() => resolve(value), ms));

const inputs = () => [later(30, "slow"), Promise.reject(new Error("broken")), later(10, "quick")];

Promise.any(inputs()).then((value) => console.log("any: " + value));

Promise.race(inputs())
  .then((value) => console.log("race: " + value))
  .catch((error) => console.log("race: " + error.message));
